import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();



export type CartoonFunnelProps = Record<string, any>;

const Car = ({ color, frame }: { color: string; frame: number }) => {
  const wheelRotation = frame * 15;
  
  return (
    <svg width={240} height={120} viewBox="0 0 240 120" style={{ overflow: "visible" }}>
      {/* Exhaust pipe */}
      <rect x="0" y="80" width="20" height="12" rx="4" fill="#475569" />
      
      {/* Chassis */}
      <path 
        d="M 30 50 L 70 20 L 150 20 L 190 50 L 220 50 A 10 10 0 0 1 230 60 L 230 90 A 10 10 0 0 1 220 100 L 20 100 A 10 10 0 0 1 10 90 L 10 60 A 10 10 0 0 1 20 50 Z" 
        fill={color} 
      />
      
      {/* Windows */}
      <path d="M 75 25 L 145 25 L 175 48 L 45 48 Z" fill="#E0F2FE" />
      <path d="M 110 25 L 110 48" stroke="#0F172A" strokeWidth="4" />
      
      {/* Tail light */}
      <path d="M 10 65 L 20 55 L 20 75 L 10 85 Z" fill="#FCA5A5" />
      
      {/* Headlight */}
      <path d="M 220 50 L 230 60 L 230 80 L 220 80 Z" fill="#FEF08A" />
      
      {/* Wheels */}
      <g style={{ transform: `rotate(${wheelRotation}deg)`, transformOrigin: "60px 100px" }}>
        <circle cx="60" cy="100" r="22" fill="#1E293B" />
        <circle cx="60" cy="100" r="10" fill="#94A3B8" />
        <path d="M 50 100 L 70 100 M 60 90 L 60 110" stroke="#F1F5F9" strokeWidth="3" />
      </g>
      
      <g style={{ transform: `rotate(${wheelRotation}deg)`, transformOrigin: "180px 100px" }}>
        <circle cx="180" cy="100" r="22" fill="#1E293B" />
        <circle cx="180" cy="100" r="10" fill="#94A3B8" />
        <path d="M 170 100 L 190 100 M 180 90 L 180 110" stroke="#F1F5F9" strokeWidth="3" />
      </g>
    </svg>
  );
};

const DollarParticle = ({ x, y, scale, opacity, color, zIndex }: any) => (
  <div style={{
    position: "absolute",
    left: x,
    top: y,
    transform: `translate(-50%, -50%) scale(${scale})`,
    opacity,
    color,
    fontSize: 64,
    fontWeight: 800,
    textShadow: "0px 4px 12px rgba(0,0,0,0.4)",
    zIndex
  }}>
    $
  </div>
);

const CartoonFunnel: React.FC<CartoonFunnelProps> = ({
  backgroundColor = "#0F172A",
  transparentBackground = false,
  durationInSeconds = 5,
  title = "Revenue Engine",
  carColor = "#EF4444",
  funnelColor = "#3B82F6",
  particleColor = "#10B981"
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Keyframes
  const durationFrames = Math.max(1, durationInSeconds) * fps;
  const driveEndFrame = Math.floor(durationFrames * 0.4);
  const fallEndFrame = Math.floor(durationFrames * 0.6);

  // Layout Dimensions
  const funnelWidth = Math.min(width * 0.8, 700);
  const funnelHeight = funnelWidth;
  const openingY = height * 0.55; 
  const openingOffset = funnelHeight * 0.2; // Based on viewBox 20% Y offset
  const funnelBoxTop = openingY - openingOffset;
  const funnelBoxLeft = (width - funnelWidth) / 2;

  // Car Trajectory Configuration
  const driveStartX = -width * 0.5;
  const driveEndX = width / 2;
  const driveY = openingY - 5;
  const fallY = openingY + funnelHeight * 0.6;

  // Car Position Calculations
  const carX = interpolate(frame, [0, driveEndFrame, fallEndFrame], [driveStartX, driveEndX, driveEndX], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  const baseCarY = interpolate(frame, [0, driveEndFrame, fallEndFrame], [driveY, driveY, fallY], { 
    easing: Easing.in(Easing.quad),
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  
  // Driving bounce effect
  const bounceAmp = interpolate(frame, [driveEndFrame - 15, driveEndFrame], [6, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const bounceY = Math.sin(frame * 0.8) * bounceAmp;
  const carY = baseCarY + bounceY;

  const carScale = interpolate(frame, [driveEndFrame, fallEndFrame], [1, 0], { 
    easing: Easing.in(Easing.quad),
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  
  const carRotation = interpolate(frame, [driveEndFrame, fallEndFrame], [0, 50], { 
    easing: Easing.in(Easing.quad),
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });

  // Particle Generators
  const numExhaustParticles = Math.floor(driveEndFrame / 4);
  const exhaustParticles = Array.from({ length: numExhaustParticles }).map((_, i) => ({
    id: i,
    spawnFrame: i * 4
  }));

  const numSpoutParticles = Math.floor((durationFrames - fallEndFrame) / 3);
  const spoutParticles = Array.from({ length: numSpoutParticles }).map((_, i) => ({
    id: i,
    spawnFrame: fallEndFrame + i * 3
  }));

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: spaceGrotesk }}>
      
      {/* Title */}
      <div style={{
        position: "absolute",
        top: height * 0.15,
        width: "100%",
        textAlign: "center",
        fontSize: 84,
        fontWeight: 900,
        color: "#FFFFFF",
        textTransform: "uppercase",
        letterSpacing: "0.02em",
        textShadow: "0px 10px 30px rgba(0,0,0,0.5)"
      }}>
        {title}
      </div>

      {/* Funnel Back Hole */}
      <div style={{ position: "absolute", left: funnelBoxLeft, top: funnelBoxTop, width: funnelWidth, height: funnelHeight }}>
        <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", overflow: "visible" }}>
          <ellipse cx="50" cy="20" rx="50" ry="15" fill="#1E3A8A" />
        </svg>
      </div>

      {/* Exhaust Particles */}
      {exhaustParticles.map((p) => {
        const age = frame - p.spawnFrame;
        if (age < 0 || age > 40) return null;

        // Trace back the car's position at the moment of spawn
        const sX = interpolate(p.spawnFrame, [0, driveEndFrame], [driveStartX, driveEndX], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        const sY = interpolate(p.spawnFrame, [0, driveEndFrame], [driveY, driveY], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        const cScale = interpolate(p.spawnFrame, [driveEndFrame, fallEndFrame], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        
        const startX = sX - (110 * cScale); // Offset to tailpipe
        const startY = sY - (40 * cScale);

        const driftX = Math.sin(age * 0.2 + p.id) * 15;
        const pX = startX - age * 5 + driftX;
        const pY = startY - age * 6;
        
        const pScale = interpolate(age, [0, 10, 40], [0.3, 1.2, 0.5]);
        const pOpacity = interpolate(age, [0, 10, 30, 40], [0, 1, 1, 0]);

        return (
          <DollarParticle 
            key={`exhaust-${p.id}`} 
            x={pX} y={pY} 
            scale={pScale} opacity={pOpacity} 
            color={particleColor} zIndex={15} 
          />
        );
      })}

      {/* Car Container */}
      <div style={{ 
        position: "absolute", 
        left: carX, 
        top: carY, 
        transform: `translate(-50%, -100%) scale(${carScale}) rotate(${carRotation}deg)`, 
        transformOrigin: "bottom center", 
        zIndex: 20 
      }}>
        <Car color={carColor} frame={frame} />
      </div>

      {/* Funnel Front Body */}
      <div style={{ 
        position: "absolute", 
        left: funnelBoxLeft, 
        top: funnelBoxTop, 
        width: funnelWidth, 
        height: funnelHeight, 
        zIndex: 30,
        pointerEvents: "none"
      }}>
        <svg viewBox="0 0 100 100" style={{ width: "100%", height: "100%", overflow: "visible" }}>
          {/* Top rim highlight */}
          <path d="M 0 20 A 50 15 0 0 0 100 20" fill="none" stroke="rgba(255,255,255,0.3)" strokeWidth="1.5" />
          {/* Main Body */}
          <path d="M 0 20 A 50 15 0 0 0 100 20 L 70 70 L 70 100 L 30 100 L 30 70 Z" fill={funnelColor} />
          {/* Shadow/Depth mapping on the left side */}
          <path d="M 0 20 A 50 15 0 0 0 50 35 L 50 100 L 30 100 L 30 70 Z" fill="rgba(0,0,0,0.15)" />
        </svg>
      </div>

      {/* Spout Output Particles */}
      {spoutParticles.map((p) => {
        const age = frame - p.spawnFrame;
        if (age < 0 || age > 90) return null;

        const startX = width / 2;
        const startY = funnelBoxTop + funnelHeight;

        const spread = ((p.id % 9) - 4) * 5; // Wide spread at the bottom
        const pX = startX + age * spread;
        const gravity = age * age * 0.25;
        const pY = startY + age * 8 + gravity;
        
        const pScale = interpolate(age, [0, 15, 90], [0, 1.5, 0.8]);
        const pOpacity = interpolate(age, [0, 10, 70, 90], [0, 1, 1, 0]);

        return (
          <DollarParticle 
            key={`spout-${p.id}`} 
            x={pX} y={pY} 
            scale={pScale} opacity={pOpacity} 
            color={particleColor} zIndex={10} 
          />
        );
      })}

    </AbsoluteFill>
  );
};

export default CartoonFunnel;